    html: "<div class=\"one-div\"></div>\r\n<style>\r\n/* From Uiverse.io by roroland  - Tags: 3d, pink, button, card, animated */\r\n.one-div {\r\n  --color1: #db41a5;\r\n  --color2: pink;\r\n  --color3: #fff;\r\n  --color4: #ffaae2;\r\n  --time: 5;\r\n  display: grid;\r\n  grid-template-columns: 1fr;\r\n  grid-template-rows: 1fr;\r\n  align-items: center;\r\n  justify-content: center;\r\n  padding: 1em;\r\n  width: auto;\r\n  height: 100%;\r\n  position: relative;\r\n  transition: all 1s ease-out;\r\n  transform: perspective(400px);\r\n  transform-style: preserve-3d;\r\n  z-index: 0;\r\n}\r\n\r\n.one-div:hover {\r\n  cursor: pointer;\r\n  filter: drop-shadow(0px 0px 100px var(--color2));\r\n  scale: 1.2;\r\n}\r\n\r\n.one-div:hover::after {\r\n  scale: 0;\r\n  opacity: 0;\r\n}\r\n\r\n.one-div:hover::before {\r\n  color: var(--color4);\r\n  box-shadow: 0px 0px 20px 5px rgba(0,0,0, .5), 0px 3px 50px rgba(0,0,0, .15), inset 0 0 1px 1px #000;\r\n  text-shadow: 0 1px 5px #000;\r\n}\r\n\r\n.one-div:active {\r\n  transition: all .1s ease-out;\r\n  scale: .99;\r\n}\r\n\r\n.one-div:active::before {\r\n  transition: all .1s ease-out;\r\n  color: white;\r\n}\r\n\r\n.one-div::after,\r\n.one-div::before {\r\n  padding: 1em;\r\n  grid-column: 1/-1;\r\n  grid-row: 1 / 1;\r\n  position: relative;\r\n  transition: all 1s ease-out .3s;\r\n}\r\n\r\n.one-div::before {\r\n  animation: fade calc(var(--time) * 1s) ease-out infinite calc(var(--time) * .5s);\r\n  content: 'Single div button';\r\n  border-radius: 4px;\r\n  background-image: linear-gradient(to bottom, var(--color1) 30%, var(--color2) 95%, var(--color3) 99%);\r\n}\r\n\r\n.one-div::after {\r\n  animation: rotate calc(var(--time) * 1s) ease-out infinite;\r\n  display: block;\r\n  width: calc(100% - 2rem);\r\n  outline-color: var(--color4);\r\n  outline-width: .5em;\r\n  outline-offset: .9em;\r\n  outline-style: solid;\r\n  content: '';\r\n  z-index: -1;\r\n}\r\n\r\n@keyframes rotate {\r\n  0% {\r\n    rotate: x -90deg;\r\n  }\r\n\r\n  0%, 50% {\r\n    filter: blur(0px) drop-shadow(0px 0px 60px var(--color3)) opacity(100%);\r\n  }\r\n\r\n  100% {\r\n    rotate: x 90deg;\r\n    filter: blur(4px) drop-shadow(0px 0px 30px var(--color2)) opacity(80%);\r\n  }\r\n}\r\n\r\n@keyframes fade {\r\n  0%, 100% {\r\n    opacity: 1;\r\n  }\r\n\r\n  50% {\r\n    opacity: 0.9;\r\n  }\r\n}\r\n</style>\r\n    ",
